#### Example 1: Compliant Multi-Module Formation

```hcl
# iac/terraform/formations/aws/app-services/main.tf

locals {
  common_tags = {
    Product     = var.product_abr
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ECS service — sourced from pfe-iac-modules, pinned to v2.3.1
module "ecs_service" {
  source = "git::ssh://git@github.com/mygainwell/pfe-iac-modules.git//modules/aws/ecs-service?ref=v2.3.1"

  product_abr   = var.product_abr
  environment   = var.environment
  cluster_arn   = data.terraform_remote_state.platform.outputs.ecs_cluster_arn
  subnet_ids    = data.terraform_remote_state.platform.outputs.private_subnet_ids
  tags          = local.common_tags
}

# SQS queue — sourced from pfe-iac-modules, pinned to v1.8.0
module "work_queue" {
  source = "git::ssh://git@github.com/mygainwell/pfe-iac-modules.git//modules/aws/sqs-queue?ref=v1.8.0"

  product_abr = var.product_abr
  environment = var.environment
  queue_name  = "claims-processing"
  tags        = local.common_tags
}

# Platform state — data source, no resource creation (permitted)
data "terraform_remote_state" "platform" {
  backend = "s3"
  config = {
    bucket = "pfe-pg-terraform-state-${var.environment}"
    key    = "platform/terraform.tfstate"
    region = var.region
  }
}
```
